let installPrompt=null;
const appEl=id=>document.getElementById(id);
function mobilePanel(panel){document.body.dataset.mobilePanel=panel;appEl('mobileBackdrop').hidden=panel==='map';for(const [id,p] of [['navMap','map'],['navFilters','filters'],['navDetails','details']]){appEl(id).setAttribute('aria-pressed',String(panel===p));if(p!=='map')appEl(id).setAttribute('aria-expanded',String(panel===p))}}
appEl('navMap').onclick=()=>mobilePanel('map');appEl('navFilters').onclick=()=>mobilePanel(document.body.dataset.mobilePanel==='filters'?'map':'filters');appEl('navDetails').onclick=()=>mobilePanel(document.body.dataset.mobilePanel==='details'?'map':'details');appEl('mobileBackdrop').onclick=()=>mobilePanel('map');document.addEventListener('keydown',e=>{if(e.key==='Escape')mobilePanel('map')});
appEl('appInfo').onclick=()=>appEl('appDialog').showModal();appEl('closeAppDialog').onclick=()=>appEl('appDialog').close();appEl('appInstall').onclick=async()=>{if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null}else appEl('appDialog').showModal()};window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});window.addEventListener('appinstalled',()=>{appEl('appInstall').textContent='Installiert'});
if(window.matchMedia('(display-mode: standalone)').matches||navigator.standalone){appEl('appInstall').hidden=true}
let swRegistration=null;
if('serviceWorker' in navigator&&window.isSecureContext){navigator.serviceWorker.register('sw.js',{scope:'./'}).then(r=>{swRegistration=r;appEl('cacheStatus').textContent='App bereit. Die Bodengrundlage kann für die Nutzung ohne Netz gespeichert werden. Zusatzebenen separat als Offline-Paket sichern.'}).catch(()=>{appEl('cacheStatus').textContent='Offline-App-Speicherung wird in diesem Browser oder dieser Vorschau nicht unterstützt. Offline-Pakete können weiterhin exportiert werden.'})}
appEl('cacheApp').onclick=async()=>{const button=appEl('cacheApp');button.disabled=true;try{if(!('caches' in window)||!swRegistration)throw Error('Offline-Speicherung ist in diesem Browser noch nicht bereit.');const r=await fetch('offline-assets.json');if(!r.ok)throw Error('Dateiliste nicht erreichbar.');const manifest=await r.json();for(let i=0;i<manifest.assets.length;i++){appEl('cacheStatus').textContent='Offline vorbereiten · '+(i+1)+' / '+manifest.assets.length;const response=await fetch(manifest.assets[i],{credentials:'same-origin'});if(!response.ok||response.redirected)throw Error('Datei nicht verfügbar. Bitte angemeldet und online erneut versuchen.')}const worker=navigator.serviceWorker.controller||swRegistration.active;if(!worker)throw Error('Bitte die App einmal neu öffnen, dann erneut sichern.');worker.postMessage({type:'CHECK_OFFLINE'});appEl('cacheStatus').textContent='Dateien abgerufen. Offline-Vollständigkeit wird geprüft …'}catch(e){appEl('cacheStatus').textContent=e.message}finally{button.disabled=false}};
if('serviceWorker' in navigator)navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='OFFLINE_STATUS')appEl('cacheStatus').textContent=e.data.complete?'Bodenkarte offline bereit. Ohne Internet zusätzlich den Offline-Modus der Karte einschalten. Gesicherte Zusatzebenen bei Bedarf als Offline-Paket öffnen.':'Noch nicht vollständig offline gespeichert ('+e.data.cached+' / '+e.data.total+'). Online erneut „Bodenkarte offline bereithalten“ wählen.'});
// Touch-Pointer: ein Finger verschiebt, zwei Finger zoomen um ihren Mittelpunkt.
async function installMobileMap(){for(let i=0;i<3000&&window.BODEN_QA?.release!=='2.5';i++)await new Promise(r=>setTimeout(r,10));if(window.BODEN_QA?.release!=='2.5')return;const active=new Map();let gesture=null,suppressClick=false;const originalDown=cv.onpointerdown,originalMove=cv.onpointermove,originalUp=cv.onpointerup,originalCancel=cv.onpointercancel;const relative=e=>{const r=cv.getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top}};const pair=()=>{const [a,b]=[...active.values()];return {x:(a.x+b.x)/2,y:(a.y+b.y)/2,d:Math.max(1,Math.hypot(a.x-b.x,a.y-b.y))}};
 cv.onpointerdown=e=>{if(e.pointerType!=='touch'){originalDown(e);return}active.set(e.pointerId,relative(e));cv.setPointerCapture(e.pointerId);if(active.size===1){suppressClick=false;originalDown(e)}else{down=null;dragged=true;suppressClick=true;const p=pair();gesture={...p,scale,worldX:(p.x-ox)/scale,worldY:(p.y-oy)/scale}}};
 cv.onpointermove=e=>{if(e.pointerType!=='touch'||!active.has(e.pointerId)){originalMove(e);return}active.set(e.pointerId,relative(e));if(active.size>=2&&gesture){const p=pair();scale=Math.max(baseScale,Math.min(baseScale*1600,gesture.scale*p.d/gesture.d));ox=p.x-gesture.worldX*scale;oy=p.y-gesture.worldY*scale;dragged=true;request()}else if(!suppressClick)originalMove(e)};
 cv.onpointerup=e=>{if(e.pointerType!=='touch'){originalUp(e);return}active.delete(e.pointerId);if(suppressClick){down=null;gesture=null;dragged=true;if(active.size===0)suppressClick=false;request();return}const wasDrag=dragged;originalUp(e);if(!wasDrag&&window.matchMedia('(max-width: 850px)').matches&&selectedPoint)mobilePanel('details')};cv.onpointercancel=e=>{active.delete(e.pointerId);gesture=null;suppressClick=active.size>0;originalCancel?.(e)};
 const oldDetail=detail;detail=function(li){oldDetail(li);if(window.matchMedia('(max-width: 850px)').matches)mobilePanel('details')};const close=document.querySelector('.detail-close');if(close){const old=close.onclick;close.onclick=()=>{old?.();mobilePanel('map')}}
 window.removeEventListener('resize',resize);const resizeObserver=new ResizeObserver(()=>{const r=appEl('stage').getBoundingClientRect();if(Math.abs(r.width-W)<1&&Math.abs(r.height-H)<1)return;const center={x:(W/2-ox)/scale,y:(H/2-oy)/scale},factor=scale/baseScale;W=r.width;H=r.height;if(!W||!H)return;const ratio=window.devicePixelRatio||1;cv.width=Math.round(W*ratio);cv.height=Math.round(H*ratio);ctx.setTransform(ratio,0,0,ratio,0,0);baseScale=Math.min(W/(DATA.bounds[2]-DATA.bounds[0]),H/(DATA.bounds[3]-DATA.bounds[1]))*.93;scale=baseScale*factor;ox=W/2-center.x*scale;oy=H/2-center.y*scale;cancelSoilRender();request()});resizeObserver.observe(appEl('stage'));window.BODEN_QA={...window.BODEN_QA,mobile_touch:true,pwa:true,hosted_data_parts:true};
}
